using System.Text.Json;
using System.Text.Json.Serialization;

namespace Stanley.Core.Tests;

/// <summary>
/// One fighter as v1 saw it: its base stats, and the maximum stats v1's Python formula
/// produced for them.
/// </summary>
/// <remarks>
/// The fixture is generated by <c>tools/golden/generate-max-stats-golden.py</c>, which runs the
/// legacy formula over <c>.old/fighters.json</c>. It is checked in so the proof survives the
/// legacy file being archived (migration plan phase 8).
/// </remarks>
public sealed record GoldenFighter(
    [property: JsonPropertyName("slug")] string Slug,
    [property: JsonPropertyName("name")] string Name,
    [property: JsonPropertyName("tier")] string Tier,
    [property: JsonPropertyName("baseAtk")] int BaseAtk,
    [property: JsonPropertyName("baseHp")] int BaseHp,
    [property: JsonPropertyName("baseFs")] int BaseFs,
    [property: JsonPropertyName("maxAtk")] int MaxAtk,
    [property: JsonPropertyName("maxHp")] int MaxHp,
    [property: JsonPropertyName("maxFs")] int MaxFs);

/// <summary>Loads the golden fixture once for every test that needs it.</summary>
public static class GoldenFighters
{
    private const string FixturePath = "Fixtures/max-stats.golden.json";

    /// <summary>All 309 fighters v1 shipped with.</summary>
    public static IReadOnlyList<GoldenFighter> All { get; } = Load();

    private static List<GoldenFighter> Load()
    {
        string path = Path.Combine(AppContext.BaseDirectory, FixturePath);
        using FileStream stream = File.OpenRead(path);

        return JsonSerializer.Deserialize<List<GoldenFighter>>(stream)
            ?? throw new InvalidOperationException($"'{path}' is empty.");
    }
}
